    },
    {
      "card_ids": ["C01"],
      "claim": "In rats, the related compound S-(-)-8 showed good initial brain uptake at 2 min after intravenous injection (1.59% dose/organ), indicating that this structural family can pass through the blood-brain barrier with ease.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple close structural analogs with direct in-vivo brain uptake data in humans, monkeys, and rats consistently show rapid and meaningful CNS access after systemic administration, supporting a pass prediction.",
